{
  "selections": [
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사가 '두려움 말고 먼저 챙기게 만드는 게 따로 있으신 건가요?'라고 물으며, 이기적이라는 두려움 너머의 정체성 수준 신념('내 욕구보다 남의 욕구가 먼저')을 탐색하고 있음. 내담자가 '항상 제가 먼저 챙기는 사람이에요'라고 말한 것이 이 신념의 표현임."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_positive",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사의 질문 '먼저 챙기게 만드는 게 따로 있으신 건가요?'는 두려움(부정적 가정) 너머의 긍정적 가정—'헌신하면 좋은 사람으로 여겨지고 곁에 둘 것이다'—을 탐색하는 것. 어린 시절 동생을 돌보거나 집안일을 하면 '우리 딸이 최고다'라는 칭찬을 받은 경험이 이 가정의 원형임."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": ["/childhood_data"],
      "relevance": "내담자가 '이기적인 사람으로 보일 것 같아요. 남들이 저한테 실망할 것 같아요'라고 직접 표현한 내용이 이 부정적 가정과 일치. 상담사가 이 두려움을 확인한 후 '그 말고'라고 확장한 것이므로 관련됨."
    },
    {
      "trait_id": "/coping_strategies/1",
      "background_ids": ["/situations/1"],
      "relevance": "내담자가 '괜찮다고 할 것 같아요. 자동으로요'라고 말하며 이 전략을 직접 언급. 가족 모임에서 '너는 원래 잘하니까'라며 역할을 맡길 때 바로 수락하고 화제를 돌리는 패턴과 연결됨."
    },
    {
      "trait_id": "/coping_strategies/4",
      "background_ids": ["/situations/1"],
      "relevance": "내담자의 최초 호소인 아이에게 소리를 지른 뒤 '내가 왜 그랬을까' 죄책감을 느끼는 것이 이 전략(폭발→죄책감→더 헌신으로 만회)과 일치. 가족 모임에서 서운함을 억누르다 차 안에서 눈물이 나는 패턴도 누적된 서운함의 폭발 전조와 유사."
    },
    {
      "trait_id": "/core_belief/young_schema",
      "background_ids": ["/situations/3"],
      "relevance": "상담사가 '두려움 말고'라고 질문하는 것은 자기희생 스키마의 정체성 수준('나는 돌보는 사람')을 확인하려는 것. 배우자가 '당신은 뭘 좋아하는지도 모르겠어'라고 말한 것은 자기 욕구가 완전히 소거된 자기희생의 극단적 표현임."
    }
  ]
}

